(()=>{var t=document.getElementById("key"),n=document.getElementById("status");chrome.storage.local.get("jevKey").then(({jevKey:e})=>{t.value=e?"••••••••":""});document.getElementById("save").onclick=async()=>{let e=t.value.trim();if(e&&!e.startsWith("•"))await chrome.storage.local.set({jevKey:e});n.textContent="Saved on this device. It's only ever sent to ai-gateway.vercel.sh when you ask Jev."};document.getElementById("clear").onclick=async()=>{await chrome.storage.local.remove("jevKey"),t.value="",n.textContent="Key removed."};})();
